// ===== AUDIO =====
const AudioContext = window.AudioContext || window.webkitAudioContext;
let audioCtx = null;
function getAudioCtx() {
  if (!audioCtx) audioCtx = new AudioContext();
  return audioCtx;
}
function playChime() {
  try {
    const ctx = getAudioCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.frequency.setValueAtTime(523, ctx.currentTime);
    osc.frequency.setValueAtTime(659, ctx.currentTime + 0.1);
    osc.frequency.setValueAtTime(784, ctx.currentTime + 0.2);
    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.4);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + 0.4);
  } catch(e) {}
}
function playBuzzer() {
  try {
    const ctx = getAudioCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(200, ctx.currentTime);
    osc.frequency.setValueAtTime(150, ctx.currentTime + 0.2);
    gain.gain.setValueAtTime(0.1, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.3);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + 0.3);
  } catch(e) {}
}

// ===== UTILITY FUNCTIONS =====
function normalizeName(name) {
  return name.toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[\-'']/g, '').replace(/\s+/g, ' ').trim();
}
function fuzzyMatch(input, target) {
  const n1 = normalizeName(input);
  const n2 = normalizeName(target);
  if (n1 === n2) return 1.0;
  if (n2.includes(n1)) return 0.9;
  if (n1.includes(n2)) return 0.85;
  // Last name match
  const targetLast = n2.split(' ').pop();
  if (n1 === targetLast) return 0.8;
  if (targetLast.includes(n1)) return 0.75;
  return 0;
}
function getTeamColors(teamName) {
  // Simple color mapping for major teams
  const colors = {
    'Argentina': '#75AADB', 'Brazil': '#009B3A', 'France': '#0055A4',
    'Germany': '#000000', 'Italy': '#0066CC', 'Spain': '#C60B1E',
    'England': '#CF081F', 'Netherlands': '#FF6600', 'Portugal': '#DA291C',
    'Uruguay': '#5B92E5', 'Croatia': '#FF0000', 'Belgium': '#EAB818',
    'Mexico': '#006847', 'Colombia': '#FCD116',
    'Switzerland': '#FF0000', 'Sweden': '#FECC02', 'Denmark': '#C60C30',
    'Poland': '#FFFFFF', 'Austria': '#ED2939', 'Hungary': '#436F4D',
    'Czechoslovakia': '#11457E', 'Soviet Union': '#CC0000', 'Yugoslavia': '#0C4076',
    'Romania': '#FCD116', 'Bulgaria': '#FFFFFF', 'Cameroon': '#007A5E',
    'Nigeria': '#008751', 'Ghana': '#006B3F', 'Morocco': '#C1272D',
    'Senegal': '#00853F', 'Turkey': '#E30A17', 'Japan': '#BC002D',
    'South Korea': '#0047A0', 'United States': '#3C3B6E', 'Costa Rica': '#CE1126',
    'Peru': '#D91023', 'Chile': '#0039A6', 'Ecuador': '#FFD100',
    'Ireland': '#169B62', 'Scotland': '#005EB8', 'Wales': '#00B140',
    'Russia': '#FFFFFF', 'Ukraine': '#0057B7', 'Paraguay': '#D52B1E',
    'Iran': '#239F40', 'Saudi Arabia': '#006C35', 'Australia': '#FFCD00',
    'Greece': '#0D5EAF', 'Serbia': '#C6363C', 'Slovenia': '#FFFFFF',
    'Slovakia': '#0B4EA2', 'Czech Republic': '#D7141A', 'Algeria': '#006233',
    'Tunisia': '#E70013', 'Egypt': '#CE1126', 'Iceland': '#02529C',
    'Panama': '#DA291C', 'Canada': '#FF0000', 'El Salvador': '#0047AB', 'New Zealand': '#000000'
  };
  for (let [key, val] of Object.entries(colors)) {
    if (teamName.toLowerCase().includes(key.toLowerCase())) return val;
  }
  return '#888888';
}

function contrastColor(hex) {
  const c = hex.replace('#', '');
  const r = parseInt(c.substring(0, 2), 16), g = parseInt(c.substring(2, 4), 16), b = parseInt(c.substring(4, 6), 16);
  return ((r * 299 + g * 587 + b * 114) / 1000) > 150 ? '#1a1206' : '#ffffff';
}

// ===== CONFETTI =====
function launchConfetti() {
  const container = document.getElementById('confetti');
  container.innerHTML = '';
  const colors = ['#ff4757', '#2ed573', '#1e90ff', '#ffa502', '#ff6b81', '#00d4aa'];
  for (let i = 0; i < 60; i++) {
    const el = document.createElement('div');
    el.className = 'confetti';
    el.style.left = Math.random() * 100 + '%';
    el.style.backgroundColor = colors[Math.floor(Math.random() * colors.length)];
    el.style.borderRadius = Math.random() > 0.5 ? '50%' : '0';
    el.style.animationDelay = Math.random() * 2 + 's';
    el.style.animationDuration = (2 + Math.random() * 2) + 's';
    container.appendChild(el);
  }
  setTimeout(() => container.innerHTML = '', 5000);
}

// ===== GAME FUNCTIONS =====
function loadLevel(levelIndex) {
  if (levelIndex >= GAME_DATA.length) {
    showGameComplete();
    return;
  }
  currentLevel = levelIndex;
  const level = GAME_DATA[levelIndex];
  lives = 3;
  correctCount = 0;
  wrongCount = 0;
  usedHints = 0;
  usedSkips = 0;
  currentCorrect = [];
  currentWrong = [];
  selectedPosition = null;

  // Update UI
  document.getElementById('level-display').textContent = (levelIndex + 1) + '/100';
  document.getElementById('score-display').textContent = score;
  updateLives();
  document.getElementById('match-title').textContent = level.match;
  document.getElementById('match-meta').textContent = level.year + ' World Cup ' + level.stage + ' • ' + level.score;

  // Timer
  const hasTimer = level.timer > 0;
  document.getElementById('timer-container').style.display = hasTimer ? 'flex' : 'none';
  if (hasTimer) {
    timeRemaining = level.timer;
    startTimer();
  } else {
    stopTimer();
    document.getElementById('timer-display').textContent = '--';
  }

  // Render pitch
  renderPitch(level);

  // Reset input
  document.getElementById('player-input').value = '';
  document.getElementById('player-input').focus();

  // Update progress
  renderProgress();

  // Announce
  announce(`Level ${levelIndex + 1}: ${level.match}, ${level.year} ${level.stage}`);
}

function posGroup(pos) {
  if (pos === 'GK') return 'GK';
  if (['CB', 'LB', 'RB', 'LWB', 'RWB', 'SW', 'DF'].includes(pos)) return 'DEF';
  if (['DM', 'CM', 'AM', 'LM', 'RM', 'MF'].includes(pos)) return 'MID';
  return 'FWD';
}

function buildFormation(containerEl, team, teamObj, color, rowOrder) {
  containerEl.innerHTML = '';

  const header = document.createElement('div');
  header.className = 'team-header';
  header.innerHTML = `<span class="swatch" style="background:${color}"></span>${teamObj.name}`;
  containerEl.appendChild(header);

  const iconText = contrastColor(color);

  const rows = { GK: [], DEF: [], MID: [], FWD: [] };
  teamObj.xi.forEach((player, i) => {
    rows[posGroup(player.pos)].push({ player, i });
  });
  Object.values(rows).forEach(row => row.sort((a, b) => a.player.x - b.player.x));

  rowOrder.forEach(rowName => {
    const entries = rows[rowName];
    if (!entries.length) return;
    const rowEl = document.createElement('div');
    rowEl.className = 'formation-row';
    entries.forEach(({ player, i }) => {
      const card = document.createElement('div');
      card.className = 'player-card';
      card.dataset.team = team;
      card.dataset.index = i;
      card.dataset.pos = player.pos;
      card.tabIndex = 0;
      card.setAttribute('role', 'button');
      card.setAttribute('aria-label', `${teamObj.name} position ${player.pos}, unguessed`);
      card.innerHTML = `
        <span class="card-icon" style="background:${color};color:${iconText}">${player.pos}</span>
        <span class="card-pos">${player.pos}</span>
        <span class="card-name"></span>
      `;
      card.addEventListener('click', () => selectPosition(team, i));
      card.addEventListener('keypress', (e) => { if (e.key === 'Enter') selectPosition(team, i); });
      rowEl.appendChild(card);
    });
    containerEl.appendChild(rowEl);
  });
}

function renderPitch(level) {
  const teamAColor = getTeamColors(level.teamA.name);
  const teamBColor = getTeamColors(level.teamB.name);

  buildFormation(document.getElementById('formationA'), 'A', level.teamA, teamAColor, ['GK', 'DEF', 'MID', 'FWD']);
  buildFormation(document.getElementById('formationB'), 'B', level.teamB, teamBColor, ['FWD', 'MID', 'DEF', 'GK']);

  // Apply hints (pre-fill)
  if (level.hints_per_team > 0) {
    // Reveal hint players
    for (let i = 0; i < Math.min(level.hints_per_team, level.teamA.xi.length); i++) {
      const player = level.teamA.xi[i];
      revealPlayer('A', i, player.name);
      currentCorrect.push({team: 'A', index: i, name: player.name});
      correctCount++;
    }
    for (let i = 0; i < Math.min(level.hints_per_team, level.teamB.xi.length); i++) {
      const player = level.teamB.xi[i];
      revealPlayer('B', i, player.name);
      currentCorrect.push({team: 'B', index: i, name: player.name});
      correctCount++;
    }
  }
}

function revealPlayer(team, index, name) {
  const level = GAME_DATA[currentLevel];
  const player = team === 'A' ? level.teamA.xi[index] : level.teamB.xi[index];

  const card = document.querySelector(`.player-card[data-team="${team}"][data-index="${index}"]`);
  if (card) {
    card.classList.add('revealed');
    card.setAttribute('aria-label', `${name} (${player.pos}) - revealed`);
    const nameEl = card.querySelector('.card-name');
    if (nameEl) nameEl.textContent = name.split(' ').pop(); // Show last name
  }
}

function selectPosition(team, index) {
  selectedPosition = {team, index};
  document.querySelectorAll('.player-card').forEach(c => c.classList.remove('active'));
  const card = document.querySelector(`.player-card[data-team="${team}"][data-index="${index}"]`);
  if (card) card.classList.add('active');
  document.getElementById('player-input').focus();
}

function submitGuess() {
  const input = document.getElementById('player-input');
  const guess = input.value.trim();
  if (!guess) return;

  const level = GAME_DATA[currentLevel];

  // Check if already guessed
  const alreadyCorrect = currentCorrect.find(c => c.name.toLowerCase() === guess.toLowerCase());
  if (alreadyCorrect) {
    input.value = '';
    return;
  }

  // Find best match among all unguessed players
  let bestMatch = null;
  let bestScore = 0;

  // Check Team A
  level.teamA.xi.forEach((player, i) => {
    if (!currentCorrect.find(c => c.team === 'A' && c.index === i)) {
      const matchScore = fuzzyMatch(guess, player.name);
      if (matchScore > bestScore && matchScore >= 0.7) {
        bestScore = matchScore;
        bestMatch = {team: 'A', index: i, player};
      }
    }
  });

  // Check Team B
  level.teamB.xi.forEach((player, i) => {
    if (!currentCorrect.find(c => c.team === 'B' && c.index === i)) {
      const matchScore = fuzzyMatch(guess, player.name);
      if (matchScore > bestScore && matchScore >= 0.7) {
        bestScore = matchScore;
        bestMatch = {team: 'B', index: i, player};
      }
    }
  });

  if (bestMatch) {
    // Correct!
    correctCount++;
    streak++;
    currentCorrect.push({team: bestMatch.team, index: bestMatch.index, name: bestMatch.player.name});

    // Calculate points
    let points = 100;
    if (level.timer > 0) points += timeRemaining * 10;
    if (streak >= 5) points = Math.floor(points * 1.5);
    score += points;

    // Reveal player
    revealPlayer(bestMatch.team, bestMatch.index, bestMatch.player.name);
    playChime();
    announce(`Correct! ${bestMatch.player.name}. +${points} points`);

    // Check level complete
    if (correctCount === 22) {
      score += 500; // Perfect bonus
      setTimeout(() => levelComplete(true), 500);
    }
  } else {
    // Wrong!
    wrongCount++;
    streak = 0;
    lives--;
    updateLives();
    playBuzzer();
    announce('Wrong guess! Lost a life.');

    // Shake effect
    input.style.borderColor = 'var(--danger)';
    setTimeout(() => input.style.borderColor = '', 300);

    if (lives <= 0) {
      setTimeout(() => levelComplete(false), 500);
    }
  }

  input.value = '';
  document.getElementById('score-display').textContent = score;
}

function updateLives() {
  const hearts = '❤️'.repeat(Math.max(0, lives));
  const broken = '♡'.repeat(Math.max(0, 3 - lives));
  document.getElementById('lives-display').innerHTML = hearts + broken;
}

function useHint() {
  if (typeof fireDirectLinkAd === 'function') fireDirectLinkAd('lineup_hint_button');
  const level = GAME_DATA[currentLevel];
  if (score < 50) {
    announce('Not enough points for a hint!');
    return;
  }

  // Find an unguessed player and reveal
  let revealed = false;
  for (let team of ['A', 'B']) {
    const xi = team === 'A' ? level.teamA.xi : level.teamB.xi;
    for (let i = 0; i < xi.length; i++) {
      if (!currentCorrect.find(c => c.team === team && c.index === i)) {
        revealPlayer(team, i, xi[i].name);
        currentCorrect.push({team, index: i, name: xi[i].name});
        correctCount++;
        score -= 50;
        usedHints++;
        revealed = true;
        document.getElementById('score-display').textContent = score;
        announce(`Hint: ${xi[i].name}`);

        if (correctCount === 22) {
          setTimeout(() => levelComplete(true), 500);
        }
        return;
      }
    }
  }
}

function skipPlayer() {
  if (score < 25) {
    announce('Not enough points to skip!');
    return;
  }
  score -= 25;
  usedSkips++;
  document.getElementById('score-display').textContent = score;
  announce('Player skipped');
}

function startTimer() {
  stopTimer();
  timerInterval = setInterval(() => {
    timeRemaining--;
    document.getElementById('timer-display').textContent = timeRemaining + 's';
    if (timeRemaining <= 0) {
      stopTimer();
      levelComplete(false);
    }
  }, 1000);
}

function stopTimer() {
  if (timerInterval) {
    clearInterval(timerInterval);
    timerInterval = null;
  }
}

function levelComplete(perfect) {
  stopTimer();

  const level = GAME_DATA[currentLevel];
  const passed = correctCount >= 14 || (correctCount > 0 && lives > 0);

  // Unlock next level
  if (passed && currentLevel + 1 >= unlockedLevel) {
    unlockedLevel = currentLevel + 2;
    localStorage.setItem('lineup_unlocked', unlockedLevel);
  }

  // Save best score
  if (score > bestScore) {
    bestScore = score;
    localStorage.setItem('lineup_best_score', bestScore);
  }

  const modal = document.createElement('div');
  modal.className = 'modal-overlay level-complete';
  modal.innerHTML = `
    <div class="modal-content">
      <h2>${perfect ? '⭐ Level Complete!' : (passed ? '✅ Level Passed' : '❌ Level Failed')}</h2>
      <p>${level.match} (${level.year})</p>
      <div class="modal-stats">
        <div class="stat-box">
          <div class="value">${correctCount}/22</div>
          <div class="label">Correct</div>
        </div>
        <div class="stat-box">
          <div class="value">${wrongCount}</div>
          <div class="label">Wrong</div>
        </div>
        <div class="stat-box">
          <div class="value">${streak}</div>
          <div class="label">Streak</div>
        </div>
        <div class="stat-box">
          <div class="value">${score}</div>
          <div class="label">Total Score</div>
        </div>
      </div>
      <div style="margin-bottom: 15px;">
        <button class="btn btn-primary" onclick="nextLevel()">Next Level →</button>
        ${currentLevel > 0 ? '<button class="btn btn-skip" onclick="retryLevel()" style="margin-left:8px;">&#128260; Retry</button>' : ''}
      </div>
      <div>
        <button class="btn btn-hint" onclick="shareResult()">&#128228; Share</button>
        <a href="../" class="btn btn-skip" style="margin-left:8px;text-decoration:none;display:inline-block;">&#9917; Try Perfect Cup</a>
      </div>
    </div>
  `;
  document.getElementById('modal-container').appendChild(modal);

  if (perfect) launchConfetti();
}

function nextLevel() {
  document.getElementById('modal-container').innerHTML = '';
  loadLevel(currentLevel + 1);
}

function retryLevel() {
  document.getElementById('modal-container').innerHTML = '';
  // Reset score for retry
  score = Math.max(0, score - correctCount * 100);
  loadLevel(currentLevel);
}

function showGameComplete() {
  const modal = document.createElement('div');
  modal.className = 'modal-overlay';
  modal.innerHTML = `
    <div class="modal-content">
      <h2>&#127942; Game Complete!</h2>
      <p>You've completed all 100 levels of LINEUP!</p>
      <div class="modal-stats">
        <div class="stat-box">
          <div class="value">${score}</div>
          <div class="label">Final Score</div>
        </div>
        <div class="stat-box">
          <div class="value">${bestScore}</div>
          <div class="label">Best Score</div>
        </div>
      </div>
      <button class="btn btn-primary" onclick="restartGame()">&#128260; Play Again</button>
      <a href="../" class="btn btn-skip" style="margin-left:8px;text-decoration:none;display:inline-block;">&#127942; More Games</a>
    </div>
  `;
  document.getElementById('modal-container').appendChild(modal);
  launchConfetti();
}

function restartGame() {
  document.getElementById('modal-container').innerHTML = '';
  currentLevel = 0;
  score = 0;
  streak = 0;
  loadLevel(0);
}

function renderProgress() {
  const bar = document.getElementById('progress-bar');
  bar.innerHTML = '';
  for (let i = 0; i < 100; i++) {
    const dot = document.createElement('div');
    dot.className = 'progress-dot';
    if (i < currentLevel) dot.classList.add('completed');
    else if (i === currentLevel) dot.classList.add('current');
    dot.title = `Level ${i + 1}`;
    bar.appendChild(dot);
  }
}

function shareResult() {
  const level = GAME_DATA[currentLevel];
  const text = `I named ${correctCount}/22 of the ${level.year} ${level.stage} lineup in LINEUP!  Can you beat me?`;
  const url = window.location.href;

  if (navigator.share) {
    navigator.share({ title: 'LINEUP - World Cup Edition', text, url });
  } else {
    // Fallback: copy to clipboard
    navigator.clipboard.writeText(text + ' ' + url).then(() => {
      announce('Copied to clipboard!');
    });
  }
}

function announce(msg) {
  // Simple screen reader announcement
  const announcer = document.createElement('div');
  announcer.className = 'sr-only';
  announcer.setAttribute('role', 'status');
  announcer.setAttribute('aria-live', 'polite');
  announcer.textContent = msg;
  document.body.appendChild(announcer);
  setTimeout(() => announcer.remove(), 1000);
}

// Keyboard handling
document.getElementById('player-input').addEventListener('keypress', (e) => {
  if (e.key === 'Enter') submitGuess();
});

// Initialize
document.addEventListener('DOMContentLoaded', () => {
  loadLevel(0);
});

